# node = [key, left, right]
def ins(t, k):
    if t is None:
        return [k, None, None]
    if k < t[0]:
        t[1] = ins(t[1], k)
    else:
        t[2] = ins(t[2], k)
    return t
def minnode(t):
    while t[1]:
        t = t[1]
    return t
def delete(t, k):
    if t is None:
        return None
    if k < t[0]:
        t[1] = delete(t[1], k)
    elif k > t[0]:
        t[2] = delete(t[2], k)
    else:
        if t[1] is None:
            return t[2]
        if t[2] is None:
            return t[1]
        s = minnode(t[2])
        t[0] = s[0]
        t[2] = delete(t[2], s[0])
    return t
